{"path": "/tmp/sv-439ceaba61734591af521966a0c90478/Components/JobApplication/StepIndicator.razor", "file_text": "
<nav class="step-indicator d-flex align-items-center justify-content-center flex-wrap gap-0" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;
        var canClick = isCompleted && !isCurrent;

        <div class="step-item text-center @(isCurrent ? "active" : isCompleted ? "completed" : "pending")"
             role="button"
             tabindex="@(canClick ? 0 : -1)"
             @onclick="() => { if (canClick) OnStepClicked.InvokeAsync(step); }">
            <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center">
                @if (isCompleted && !isCurrent)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@step</span>
                }
            </div>
            <small class="step-label d-block">@StepNames[i]</small>
        </div>

        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector flex-shrink-0 @(isCompleted ? "completed" : "")"></div>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}
"}

