.step-item {
    min-width: 90px;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step-item.active {
    opacity: 1;
}

.step-item.completed {
    opacity: 1;
    cursor: pointer;
}

.step-circle {
    width: 38px;
    height: 38px;
    background: #dee2e6;
    font-weight: 600;
    font-size: 0.9rem;
    color: #6c757d;
    transition: background 0.2s, color 0.2s;
}

.step-item.active .step-circle {
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    background: #198754;
    color: #fff;
}

.step-label {
    font-size: 0.72rem;
    color: #6c757d;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    height: 2px;
    width: 36px;
    background: #dee2e6;
    margin-bottom: 1.4rem;
}

.step-connector.completed {
    background: #198754;
}

