@using sv_439ceaba61734591af521966a0c90478.Models
@inject IApplicationService ApplicationService

<EditForm Model="Model" OnValidSubmit="HandleNext" FormName="personalInfo">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <InputText class="form-control" @bind-Value="Model.FullName" />
        <ValidationMessage For="() => Model.FullName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email *</label>
        <InputText class="form-control" @bind-Value="Model.Email" />
        <ValidationMessage For="() => Model.Email" />
        @if (!string.IsNullOrEmpty(emailError))
        {
            <div class="text-danger small mt-1">@emailError</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <InputText class="form-control" @bind-Value="Model.Phone" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address *</label>
        <InputText class="form-control" @bind-Value="Model.Address" />
        <ValidationMessage For="() => Model.Address" />
    </div>

    @if (isValidating)
    {
        <p class="text-primary fst-italic small">Validating email…</p>
    }

    <div class="d-flex justify-content-end pt-3 border-top">
        <button type="submit" class="btn btn-primary" disabled="@isValidating">Next</button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private string? emailError;
    private bool isValidating;

    private async Task HandleNext()
    {
        emailError = null;
        isValidating = true;

        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                emailError = "This email address could not be validated.";
                return;
            }

            await OnNext.InvokeAsync();
        }
        finally
        {
            isValidating = false;
        }
    }
}

@using sv_439ceaba61734591af521966a0c90478.Models

<div>
    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-primary btn-sm" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (errors.Count > 0)
    {
        <div class="alert alert-danger mt-3 py-2">
            @foreach (var error in errors)
            {
                <div class="small">@error</div>
            }
        </div>
    }

    <div class="d-flex justify-content-between pt-3 mt-3 border-top">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<string> errors = new();

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        errors.Clear();

        for (int i = 0; i < Entries.Count; i++)
        {
            var e = Entries[i];
            if (string.IsNullOrWhiteSpace(e.Company))
                errors.Add($"Position {i + 1}: Company name is required.");
            if (string.IsNullOrWhiteSpace(e.Title))
                errors.Add($"Position {i + 1}: Job title is required.");
            if (e.StartDate is null)
                errors.Add($"Position {i + 1}: Start date is required.");
        }

        if (errors.Count == 0)
            await OnNext.InvokeAsync();
    }
}

@using sv_439ceaba61734591af521966a0c90478.Models

<div>
    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]"
                       Index="index"
                       ShowRemove="References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-primary btn-sm" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (errors.Count > 0)
    {
        <div class="alert alert-danger mt-3 py-2">
            @foreach (var error in errors)
            {
                <div class="small">@error</div>
            }
        </div>
    }

    <div class="d-flex justify-content-between pt-3 mt-3 border-top">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<string> errors = new();

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        errors.Clear();

        for (int i = 0; i < References.Count; i++)
        {
            var r = References[i];
            if (string.IsNullOrWhiteSpace(r.Name))
                errors.Add($"Reference {i + 1}: Name is required.");
            if (string.IsNullOrWhiteSpace(r.Relationship))
                errors.Add($"Reference {i + 1}: Relationship is required.");
            if (string.IsNullOrWhiteSpace(r.Email))
                errors.Add($"Reference {i + 1}: Email is required.");
            if (string.IsNullOrWhiteSpace(r.Phone))
                errors.Add($"Reference {i + 1}: Phone is required.");
        }

        if (errors.Count == 0)
            await OnNext.InvokeAsync();
    }
}

@using sv_439ceaba61734591af521966a0c90478.Models

<div>
    @* Personal Info *@
    <div class="mb-4 pb-3 border-bottom">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Personal Information</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        <dl class="row mb-0">
            <dt class="col-sm-3">Full Name</dt>
            <dd class="col-sm-9">@PersonalInfo.FullName</dd>
            <dt class="col-sm-3">Email</dt>
            <dd class="col-sm-9">@PersonalInfo.Email</dd>
            <dt class="col-sm-3">Phone</dt>
            <dd class="col-sm-9">@PersonalInfo.Phone</dd>
            <dt class="col-sm-3">Address</dt>
            <dd class="col-sm-9">@PersonalInfo.Address</dd>
        </dl>
    </div>

    @* Work History *@
    <div class="mb-4 pb-3 border-bottom">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Work History</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-2">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="text-muted small">
                    @entry.StartDate?.ToString("MMM yyyy") —
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <div class="small mt-1">@entry.Description</div>
                }
            </div>
        }
    </div>

    @* References *@
    <div class="mb-4 pb-3 border-bottom">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">References</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong> <span class="text-muted">(@r.Relationship)</span>
                <div class="small">@r.Email · @r.Phone</div>
            </div>
        }
    </div>

    @* Cover Letter *@
    <div class="mb-4 pb-3 border-bottom">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Cover Letter</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(4)">Edit</button>
        </div>
        <div class="bg-light rounded p-3 small" style="white-space: pre-wrap;">@CoverLetter</div>
    </div>

    @* Submit *@
    <div class="d-flex justify-content-end pt-2">
        <button type="button" class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-2" role="status"></span>
                <span>Submitting…</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
}

