@using sv_439ceaba61734591af521966a0c90478.Models

<div>
    @* Personal Info *@
    <div class="mb-4 pb-3 border-bottom">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Personal Information</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        <dl class="row mb-0">
            <dt class="col-sm-3">Full Name</dt>
            <dd class="col-sm-9">@PersonalInfo.FullName</dd>
            <dt class="col-sm-3">Email</dt>
            <dd class="col-sm-9">@PersonalInfo.Email</dd>
            <dt class="col-sm-3">Phone</dt>
            <dd class="col-sm-9">@PersonalInfo.Phone</dd>
            <dt class="col-sm-3">Address</dt>
            <dd class="col-sm-9">@PersonalInfo.Address</dd>
        </dl>
    </div>

    @* Work History *@
    <div class="mb-4 pb-3 border-bottom">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Work History</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-2">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="text-muted small">
                    @entry.StartDate?.ToString("MMM yyyy") —
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <div class="small mt-1">@entry.Description</div>
                }
            </div>
        }
    </div>

    @* References *@
    <div class="mb-4 pb-3 border-bottom">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">References</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong> <span class="text-muted">(@r.Relationship)</span>
                <div class="small">@r.Email · @r.Phone</div>
            </div>
        }
    </div>

    @* Cover Letter *@
    <div class="mb-4 pb-3 border-bottom">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Cover Letter</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(4)">Edit</button>
        </div>
        <div class="bg-light rounded p-3 small" style="white-space: pre-wrap;">@CoverLetter</div>
    </div>

    @* Submit *@
    <div class="d-flex justify-content-end pt-2">
        <button type="button" class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-2" role="status"></span>
                <span>Submitting…</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
}

