@page "/apply"
@rendermode InteractiveServer
@using sv_439ceaba61734591af521966a0c90478.Models
@using sv_439ceaba61734591af521966a0c90478.Components.JobApplication
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 760px;">
    <h1 class="text-center mb-4">Job Application</h1>

    @if (submittedId.HasValue)
    {
        <div class="text-center py-5">
            <div class="bg-success text-white rounded-circle d-inline-flex align-items-center justify-content-center mb-3"
                 style="width: 64px; height: 64px; font-size: 2rem;">
                ✓
            </div>
            <h2>Application Submitted!</h2>
            <p class="text-muted">Your application has been received. Your application ID is:</p>
            <p class="fs-3 fw-bold text-primary">#@submittedId</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep"
                       CompletedSteps="completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="card mt-4">
            <div class="card-body p-4">
                @switch (currentStep)
                {
                    case 1:
                        <h4 class="card-title mb-3">Personal Information</h4>
                        <PersonalInfoStep Model="personalInfo" OnNext="AdvanceFromCurrentStep" />
                        break;
                    case 2:
                        <h4 class="card-title mb-3">Work History</h4>
                        <WorkHistoryStep Entries="workEntries"
                                         OnNext="AdvanceFromCurrentStep"
                                         OnBack="PreviousStep" />
                        break;
                    case 3:
                        <h4 class="card-title mb-3">References</h4>
                        <ReferencesStep References="references"
                                        OnNext="AdvanceFromCurrentStep"
                                        OnBack="PreviousStep" />
                        break;
                    case 4:
                        <h4 class="card-title mb-3">Cover Letter</h4>
                        <CoverLetterStep @bind-CoverLetter="coverLetter"
                                         OnNext="AdvanceFromCurrentStep"
                                         OnBack="PreviousStep" />
                        break;
                    case 5:
                        <h4 class="card-title mb-3">Review &amp; Submit</h4>
                        <ReviewStep PersonalInfo="personalInfo"
                                    WorkEntries="workEntries"
                                    References="references"
                                    CoverLetter="coverLetter"
                                    OnEditSection="GoToStep"
                                    OnSubmit="SubmitApplication"
                                    IsSubmitting="isSubmitting" />
                        break;
                }
            </div>
        </div>
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private int? submittedId;
    private bool isSubmitting;

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void AdvanceFromCurrentStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 1)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate!.Value,
                    e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

using sv_439ceaba61734591af521966a0c90478.Models;

namespace sv_439ceaba61734591af521966a0c90478.Services;

/// <summary>
/// Stub implementation for development. Replace with a real implementation.
/// </summary>
public class StubApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1500); // simulate network latency
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500); // simulate network latency
        return !string.IsNullOrWhiteSpace(email) && email.Contains('@');
    }
}

